@@ -1,14 +1,38 @@
 package clinic;

 import java.time.LocalDate;
 import java.util.List;

+/** Наряд на приём. На record — короче и сравнивается по значению. */
+public record WorkOrder(String petId, LocalDate day, List<String> services) {
+
+    /** Переносит наряд на другой день. Исходный не трогаем. */
+    public WorkOrder movedTo(LocalDate other) {
+        WorkOrder moved = new WorkOrder(petId, other, services);
+        moved.services().add("перенос");
+
+        return moved;
+    }
+
+    public boolean sameAs(WorkOrder other) {
+        return equals(other);
+    }
+}
